use shop::api;

#[test]
fn rejects_empty_cart() {
    assert!(api::checkout(&[]).is_err());
}

#[test]
fn rejects_negative_price() {
    assert!(api::price(-1).is_err());
}

#[test]
fn totals_items() {
    assert_eq!(api::total(&[1, 2, 3]), 6);
}

#[test]
fn applies_discount() {
    assert_eq!(api::discount(100, 10), 90);
}

